from pathlib import Path
p=Path(__file__).resolve().parents[1]/'app/src/main/assets/index.html'
s=p.read_text(encoding='utf-8')
if 'living-dex-reference-faithful" content="4.5"' not in s:s=s.replace('</head>','<meta name="living-dex-reference-faithful" content="4.5"/>\n</head>',1)
css=r'''
/* Reference Faithful 4.5 — library + Paldea map rebuilt from the approved visual target. */
:root{--rf45-bg:#f7f9fd;--rf45-ink:#111b36;--rf45-muted:#8792a8;--rf45-red:#ff5158;--rf45-line:#e8edf5;--rf45-green:#27c67b}
body.reference-v4{background:radial-gradient(circle at 100% 0,#fff0f1 0,transparent 27%),linear-gradient(180deg,#f8faff,#f4f7fc)!important;color:var(--rf45-ink)}
/* GENERAL */
#games{max-width:980px;margin:0 auto!important;padding:18px 20px 104px!important}
#games .nav23-general-switch{position:sticky;top:54px;z-index:22;margin:4px 0 20px!important;border-radius:24px!important;padding:7px!important;background:rgba(255,255,255,.96)!important;box-shadow:0 10px 30px rgba(29,42,76,.08)!important}
#games .nav23-general-switch button{font-size:14px!important;font-weight:800!important;border-radius:18px!important}.nav23-general-switch button.active{background:#fff0f0!important;color:var(--rf45-red)!important}
#games .games-grid,#games .game-grid{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:16px!important}
#games .game-card{position:relative!important;padding:0 14px 14px!important;border-radius:25px!important;overflow:hidden!important;background:#fff!important;border:1px solid rgba(229,234,243,.9)!important;box-shadow:0 10px 28px rgba(29,42,76,.075)!important}
.r45-game-art{height:124px;margin:0 -14px 12px;overflow:hidden;background:#edf1f7}.r45-game-art img{width:100%;height:100%;display:block;object-fit:cover}.r45-game-platform{font-size:9px;font-weight:900;letter-spacing:.12em;color:#929bad;text-transform:uppercase;margin-bottom:7px}.r45-current{position:absolute;right:10px;top:10px;padding:5px 9px;border-radius:12px;background:#fff0f1;color:var(--rf45-red);font-size:9px;font-weight:900;box-shadow:0 3px 10px rgba(24,38,68,.08)}
#games .game-card h3,#games .game-card h4{font-size:15px!important;line-height:1.14!important;margin:4px 0!important;color:var(--rf45-ink)!important}.r45-dexname{font-size:10px;color:var(--rf45-muted);margin:0 0 8px}.r45-progressline{height:6px;border-radius:99px;background:#edf1f5;overflow:hidden;margin:7px 0 12px}.r45-progressline i{display:block;height:100%;border-radius:99px;background:var(--rf45-green)}
#games .game-card button{border-radius:14px!important;font-size:11px!important;font-weight:850!important}.r45-open{background:var(--rf45-red)!important;color:#fff!important;border:0!important}.r45-set{background:#f5f7fa!important;color:#647086!important;border:1px solid #edf0f5!important}.r45-set.current{background:#e9fbf5!important;color:#168b65!important}
/* MAP */
#ref42MapPage{background:#76bfd1!important}.ref42-pagehead{height:126px!important;padding:calc(14px + env(safe-area-inset-top)) 18px 12px!important;background:linear-gradient(180deg,rgba(248,251,255,.98),rgba(241,248,253,.94))!important;border-bottom:1px solid rgba(255,255,255,.7)!important;box-shadow:none!important}.ref42-pagehead h2{font-size:27px!important;letter-spacing:-.045em!important}.ref42-pagehead p{font-size:11px!important;color:#8c97a9!important}.ref42-content{top:126px!important;background:#77bed0!important}.ref43-mapviewport{background:#77bed0!important}.ref43-mapcanvas{min-width:100%;min-height:100%;background:#77bed0}.paldea-map{position:absolute!important;inset:0!important;min-height:100%!important;background:#77bed0!important;overflow:hidden}.paldea-map-art{position:absolute!important;left:50%!important;top:49%!important;width:min(94vw,760px)!important;height:auto!important;max-height:78vh!important;object-fit:contain!important;transform:translate(-50%,-50%)!important;filter:saturate(1.05) contrast(1.02)!important;border-radius:28px!important;box-shadow:0 16px 50px rgba(16,67,91,.16)!important}.map-caption{left:18px!important;top:18px!important;padding:10px 16px!important;border-radius:18px!important;text-transform:uppercase;font-size:10px!important;font-weight:900!important;letter-spacing:.08em!important}.ref43-controls{top:26px!important;right:18px!important;gap:10px!important}.ref43-controls button{width:52px!important;height:52px!important;border-radius:17px!important;font-size:24px!important;background:rgba(255,255,255,.96)!important}.geo-node{width:42px!important;height:52px!important;border-radius:50% 50% 50% 12px!important;transform:translate(-50%,-50%) rotate(-45deg)!important;font-size:0!important}.geo-node:after{content:attr(data-n)!important;display:grid;place-items:center;width:100%;height:100%;transform:rotate(45deg)!important;font-size:11px!important;color:#fff;font-weight:900}.geo-node.gym{background:#468be9!important}.geo-node.titan{background:#eea13d!important}.geo-node.star{background:#e84e72!important}.geo-node.next{background:#ff5158!important;width:48px!important;height:58px!important;box-shadow:0 0 0 6px rgba(255,255,255,.72),0 8px 20px rgba(35,48,79,.3)!important}.route-polyline polyline{stroke:rgba(255,255,255,.9)!important;stroke-width:1.4!important;stroke-dasharray:2.8 3.2!important}.ref43-detail{left:18px!important;right:18px!important;bottom:calc(18px + env(safe-area-inset-bottom))!important;border-radius:25px!important;padding:16px!important}.ref43-num{border-radius:50%!important;background:var(--rf45-red)!important;color:#fff!important}.ref43-primary{background:var(--rf45-red)!important}.ref43-secondary{background:#f3f6fa!important}.r45-map-tabs{position:absolute;left:18px;right:84px;top:82px;z-index:34;display:flex;gap:7px}.r45-map-tabs span{padding:8px 11px;border-radius:14px;background:rgba(255,255,255,.92);font-size:9px;font-weight:850;color:#5d6980}.r45-map-tabs span:first-child{background:var(--rf45-red);color:#fff}
@media(max-width:680px){#games{padding:12px 14px 94px!important}#games .games-grid,#games .game-grid{gap:11px!important}.r45-game-art{height:92px}.paldea-map-art{width:96vw!important;max-height:72vh!important}.ref42-pagehead h2{font-size:25px!important}.geo-node{width:36px!important;height:44px!important}.geo-node.next{width:42px!important;height:50px!important}}
'''
s=s.replace('</style>',css+'\n</style>',1)
js=r'''
const R45_ART={letsgo:'letsgo.jpg',swsh:'swsh.jpg',bdsp:'bdsp.jpg',arceus:'arceus.jpg',sv:'sv.jpg',za:'za.jpg'};
function r45GameId(card){const t=(card.textContent||'').toLowerCase();if(t.includes("let's go"))return'letsgo';if(t.includes('sword')||t.includes('shield'))return'swsh';if(t.includes('brilliant')||t.includes('shining'))return'bdsp';if(t.includes('arceus'))return'arceus';if(t.includes('scarlet')||t.includes('violet'))return'sv';if(t.includes('z-a')||t.includes('z–a'))return'za';return''}
function r45Library(){document.querySelectorAll('#games .game-card').forEach(card=>{const id=r45GameId(card);if(!id)return;if(!card.querySelector('.r45-game-art')){const art=document.createElement('div');art.className='r45-game-art';art.innerHTML=`<img src="assets/ui45/${R45_ART[id]}" alt="Arte ${id}" loading="lazy">`;card.prepend(art)}const current=id===state.activeGameId;if(current&&!card.querySelector('.r45-current'))card.insertAdjacentHTML('afterbegin','<span class="r45-current">Jogando agora</span>');card.querySelectorAll('button').forEach(b=>{const tx=(b.textContent||'').toLowerCase();if(tx.includes('abrir'))b.classList.add('r45-open');if(tx.includes('definir')||tx.includes('jogo atual')){b.classList.add('r45-set');if(current)b.classList.add('current')}});const h=card.querySelector('h3,h4');if(h&&!card.querySelector('.r45-game-platform'))h.insertAdjacentHTML('beforebegin',`<div class="r45-game-platform">${id==='za'?'Nintendo Switch / Switch 2':'Nintendo Switch'}</div>`)});document.documentElement.dataset.r45Library='1'}
function r45MapDecorate(){const p=document.getElementById('ref42MapPage');if(!p)return;const img=p.querySelector('.paldea-map-art');if(img)img.src='assets/ui45/paldea-map.jpg';p.querySelectorAll('.geo-node').forEach((n,i)=>n.dataset.n=String(i+1));const v=p.querySelector('.ref43-mapviewport');if(v&&!v.querySelector('.r45-map-tabs'))v.insertAdjacentHTML('afterbegin','<div class="r45-map-tabs"><span>Rota por nível</span><span>18 objetivos</span></div>');document.documentElement.dataset.r45Map='1'}
const r45Go=window.go;if(typeof r45Go==='function')window.go=function(){const r=r45Go.apply(this,arguments);setTimeout(r45Library,50);return r};
const r45Map=window.ref42RenderMap;if(typeof r45Map==='function')window.ref42RenderMap=function(){const r=r45Map.apply(this,arguments);setTimeout(r45MapDecorate,20);return r};
setTimeout(()=>{r45Library();r45MapDecorate()},120);
if(new URLSearchParams(location.search).has('r45qa'))setTimeout(()=>{const arts=[...document.querySelectorAll('#games .r45-game-art img')];const ok=document.querySelector('meta[name="living-dex-reference-faithful"][content="4.5"]')&&arts.length>=6&&arts.every(i=>i.getAttribute('src')?.startsWith('assets/ui45/'));if(ok)document.documentElement.dataset.r45Qa='1'},700);
'''
s=s.replace('</body>','<script>'+js+'</script>\n</body>',1)
p.write_text(s,encoding='utf-8')
print('Reference Faithful 4.5 applied')
